import subprocess
import pprint

def get_git_log():
    cmd = ["git", "log", "--all", "--format=%H|%P|%D|%s|%cd|%an", "--date=format:%Y-%m-%d %H:%M:%S", "--date-order"]
    out = subprocess.check_output(cmd, text=True).strip()
    commits = []
    for line in out.splitlines():
        parts = line.split("|", 5)
        if len(parts) == 6:
            commits.append({
                "hash": parts[0],
                "parents": parts[1].split(),
                "tags": parts[2],
                "msg": parts[3],
                "date": parts[4],
                "author": parts[5]
            })
    return commits

commits = get_git_log()
active_cols = []
for c in commits:
    chash = c["hash"]
    if chash not in active_cols:
        active_cols.append(chash)

    col = active_cols.index(chash)

    # routing
    indices = [i for i, x in enumerate(active_cols) if x == chash]
    if len(indices) > 1:
        # emit routing row
        route_row = [" "] * (max(indices)*2 + 2)
        route_row[indices[0]*2] = '├'
        route_row[indices[-1]*2] = '╯'
        for i in range(indices[0]+1, indices[-1]):
            if i in indices:
                route_row[i*2] = '┴'
                route_row[i*2-1] = '─'
                route_row[i*2+1] = '─'
            else:
                if active_cols[i] is not None:
                    route_row[i*2] = '┼'
                else:
                    route_row[i*2] = '─'
                route_row[i*2-1] = '─'
                route_row[i*2+1] = '─'
        print("".join(route_row))
        # merge
        for i in indices[1:]:
            active_cols[i] = None

    col = indices[0]

    # render row
    row = [" "] * (len(active_cols)*2 + 2)
    for i, a in enumerate(active_cols):
        if a is not None:
            row[i*2] = '│'

    row[col*2] = '●'

    parents = c["parents"]
    if len(parents) > 0:
        p1 = parents[0]
        active_cols[col] = p1
        for p in parents[1:]:
            if p in active_cols:
                d = active_cols.index(p)
                if d > col:
                    row[d*2] = '┤'
                    for x in range(col*2+1, d*2):
                        if x % 2 == 0:
                            row[x] = '┼' if active_cols[x//2] is not None else '─'
                        else:
                            row[x] = '─'
                elif d < col:
                    row[d*2] = '├'
                    for x in range(d*2+1, col*2):
                        if x % 2 == 0:
                            row[x] = '┼' if active_cols[x//2] is not None else '─'
                        else:
                            row[x] = '─'
            else:
                d = len(active_cols)
                if None in active_cols[col+1:]:
                    d = active_cols.index(None, col+1)
                else:
                    active_cols.append(None)
                    d = len(active_cols) - 1
                active_cols[d] = p
                row[d*2] = '╮'
                for x in range(col*2+1, d*2):
                    if x % 2 == 0:
                        row[x] = '┼' if active_cols[x//2] is not None else '─'
                    else:
                        row[x] = '─'
    else:
        active_cols[col] = None

    # remove trailing Nones
    while active_cols and active_cols[-1] is None:
        active_cols.pop()

    print("".join(row) + "  " + c["msg"])
