import sys
import os
import subprocess
import curses
import time

def run_git(args):
    try:
        return subprocess.check_output(['git'] + args, text=True, stderr=subprocess.DEVNULL).strip()
    except:
        return ""

def get_git_info():
    out = run_git(["log", "--all", "--format=%H|%P|%D|%s|%cd|%an", "--date=format:%Y-%m-%d %H:%M:%S", "--date-order"])
    commits = []
    for line in out.splitlines():
        parts = line.split("|", 5)
        if len(parts) == 6:
            # Parse tags
            raw_tags = parts[2].split(",")
            tags = []
            for t in raw_tags:
                t = t.strip()
                if t.startswith("HEAD -> "):
                    tags.append(t[8:])
                elif t.startswith("tag: "):
                    pass # ignore tags? keifu only shows branches?
                elif t:
                    tags.append(t)

            commits.append({
                "hash": parts[0],
                "parents": parts[1].split(),
                "tags": tags,
                "msg": parts[3],
                "date_full": parts[4],
                "date_short": parts[4].split()[0],
                "author": parts[5]
            })
    repo_name = os.path.basename(run_git(["rev-parse", "--show-toplevel"]))
    head = run_git(["branch", "--show-current"])
    if not head:
        head = "HEAD"
    return commits, repo_name, head

