class App:
    def __init__(self, stdscr):
        self.stdscr = stdscr
        curses.start_color()
        curses.use_default_colors()

        # Color initialization
        for i, fg in enumerate([12, 2, 5, 3, 1, 14, 8, 6, 4, 15, 0, 10, 11, 13, 9]):
            curses.init_pair(i+1, fg, -1)
            curses.init_pair(i+21, fg, 8)

        curses.init_pair(41, 0, 5) # status: repo
        curses.init_pair(42, 0, 2) # status: branch
        curses.init_pair(43, 0, 6) # status: keys
        curses.init_pair(44, 15, -1) # status: text
        curses.init_pair(45, 0, 3) # status: INPUT

        self.commits, self.repo, self.head = get_git_info()
        self.cursor = 0
        self.scroll = 0
        self.tag_idx = [0] * len(self.commits)

        # UI state
        self.search_mode = False
        self.search_query = ""
        self.search_matches = []
        self.search_sel = 0

        self.branch_mode = False
        self.branch_query = ""

        self.last_refresh = time.time()

        self.run()

    def refresh_data(self):
        old_hash = self.commits[self.cursor]["hash"] if self.commits else None
        self.commits, self.repo, self.head = get_git_info()
        self.tag_idx = [0] * len(self.commits)
        if old_hash:
            for i, c in enumerate(self.commits):
                if c["hash"] == old_hash:
                    self.cursor = i
                    break

    def run(self):
        self.stdscr.nodelay(True)
        while True:
            self.draw()
            try:
                ch = self.stdscr.getch()
            except:
                ch = -1
            if ch != -1:
                if self.search_mode:
                    pass
                elif self.branch_mode:
                    pass
                else:
                    if ch == ord('q') or ch == 27:
                        break
                    elif ch == ord('j') or ch == curses.KEY_DOWN:
                        if self.cursor < len(self.commits) - 1:
                            self.cursor += 1
                    elif ch == ord('k') or ch == curses.KEY_UP:
                        if self.cursor > 0:
                            self.cursor -= 1
            if time.time() - self.last_refresh > 10:
                self.refresh_data()
                self.last_refresh = time.time()
            time.sleep(0.01)

    def draw(self):
        self.stdscr.erase()
        h, w = self.stdscr.getmaxyx()

        # Layout:
        # top box: 0 to h-10
        # detail box: h-10 to h-2 (left half)
        # files box: h-10 to h-2 (right half)
        # status: h-1

        self.stdscr.refresh()
