def build_graph(commits):
    active_cols = []
    col_colors = []
    next_color = 0
    rows = [] # list of lists: (char, color)
    for c in commits:
        chash = c["hash"]
        if chash not in active_cols:
            if None in active_cols:
                idx = active_cols.index(None)
                active_cols[idx] = chash
                if idx >= len(col_colors):
                    col_colors.append(next_color % 6)
                    next_color += 1
            else:
                active_cols.append(chash)
                col_colors.append(next_color % 6)
                next_color += 1

        indices = [i for i, x in enumerate(active_cols) if x == chash]
        if len(indices) > 1:
            route_row = [(" ", 6)] * (len(active_cols)*2)
            c_min = indices[0]
            c_max = indices[-1]
            base_col = col_colors[c_min]
            route_row[c_min*2] = ('├', base_col)
            route_row[c_max*2] = ('╯', col_colors[c_max])
            for x in range(c_min*2 + 1, c_max*2):
                if x % 2 == 0:
                    col = x // 2
                    if col in indices:
                        route_row[x] = ('┴', col_colors[col])
                    else:
                        route_row[x] = ('┼', col_colors[col]) if active_cols[col] is not None else ('─', base_col)
                else:
                    route_row[x] = ('─', base_col) # line color is base_col? Or should it take the color of the column it merges from?

            for i in range(len(active_cols)):
                if active_cols[i] is not None and i not in indices:
                    if i < c_min or i > c_max:
                        route_row[i*2] = ('│', col_colors[i])

            rows.append(("routing", route_row))
            for i in indices[1:]:
                active_cols[i] = None

        col = active_cols.index(chash)
        row = [(" ", 6)] * (len(active_cols)*2)
        for i, a in enumerate(active_cols):
            if a is not None:
                row[i*2] = ('│', col_colors[i])

        # draw HEAD marker or normal marker
        is_head = "HEAD" in c["tags"] or any(t == "main" for t in c["tags"]) # rough check
        row[col*2] = ('◉' if is_head else '●', col_colors[col])

        parents = c["parents"]
        if len(parents) > 0:
            p1 = parents[0]
            active_cols[col] = p1
            for p in parents[1:]:
                if p in active_cols:
                    d = active_cols.index(p)
                    if d > col:
                        row[d*2] = ('┤', col_colors[d])
                        for x in range(col*2+1, d*2):
                            if x % 2 == 0:
                                row[x] = ('┼', col_colors[x//2]) if active_cols[x//2] is not None else ('─', col_colors[col])
                            else:
                                row[x] = ('─', col_colors[col])
                    elif d < col:
                        row[d*2] = ('├', col_colors[d])
                        for x in range(d*2+1, col*2):
                            if x % 2 == 0:
                                row[x] = ('┼', col_colors[x//2]) if active_cols[x//2] is not None else ('─', col_colors[d])
                            else:
                                row[x] = ('─', col_colors[d])
                else:
                    if None in active_cols[col+1:]:
                        d = active_cols.index(None, col+1)
                    else:
                        active_cols.append(None)
                        d = len(active_cols) - 1
                        col_colors.append(next_color % 6)
                        next_color += 1
                        row.extend([(" ", 6), (" ", 6)])
                    active_cols[d] = p
                    row[d*2] = ('╮', col_colors[col])
                    for x in range(col*2+1, d*2):
                        if x % 2 == 0:
                            row[x] = ('┼', col_colors[x//2]) if active_cols[x//2] is not None else ('─', col_colors[col])
                        else:
                            row[x] = ('─', col_colors[col])
        else:
            active_cols[col] = None

        while active_cols and active_cols[-1] is None:
            active_cols.pop()

        # trim spaces from right
        while row and row[-1][0] == " ":
            row.pop()

        rows.append(("commit", row, c))
    return rows
