def run_git(args):
    try:
        return subprocess.check_output(['git'] + args, text=True, stderr=subprocess.DEVNULL).strip()
    except Exception:
        return ""

def get_git_info():
    out = run_git(["log", "--all", "--format=%H|%P|%D|%s|%cd|%an", "--date=format:%Y-%m-%d %H:%M:%S", "--date-order"])
    if not out:
        return [], "repo", "HEAD"
    commits = []
    for line in out.splitlines():
        parts = line.split("|", 5)
        if len(parts) == 6:
            raw_tags = parts[2].split(",")
            tags = []
            for t in raw_tags:
                t = t.strip()
                if not t or "tag: " in t: continue
                if t.startswith("HEAD -> "):
                    tags.append(t[8:])
                else:
                    tags.append(t)
            commits.append({
                "hash": parts[0], "parents": parts[1].split(),
                "tags": tags, "msg": parts[3],
                "date_full": parts[4], "date_short": parts[4].split()[0],
                "author": parts[5]
            })
    toplevel = run_git(["rev-parse", "--show-toplevel"])
    repo_name = os.path.basename(toplevel) if toplevel else "repo"
    head = run_git(["branch", "--show-current"])
    if not head: head = "HEAD"
    return commits, repo_name, head

def build_graph(commits, head_hash):
    active_cols = []
    col_colors = []
    next_color = 0
    rows = []
    for i, c in enumerate(commits):
        chash = c["hash"]
        if chash not in active_cols:
            if None in active_cols:
                idx = active_cols.index(None)
                active_cols[idx] = chash
                col_colors[idx] = next_color % 6
                next_color += 1
            else:
                active_cols.append(chash)
                col_colors.append(next_color % 6)
                next_color += 1

        indices = [j for j, x in enumerate(active_cols) if x == chash]
        if len(indices) > 1:
            route_row = [(" ", 6)] * (len(active_cols)*2)
            c_min = indices[0]
            c_max = indices[-1]
            base_col = col_colors[c_min]
            route_row[c_min*2] = ('├', base_col)
            route_row[c_max*2] = ('╯', col_colors[c_max])
            for x in range(c_min*2 + 1, c_max*2):
                if x % 2 == 0:
                    col = x // 2
                    if col in indices:
                        route_row[x] = ('┴', col_colors[col])
                    else:
                        route_row[x] = ('┼', col_colors[col]) if active_cols[col] is not None else ('─', base_col)
                else:
                    route_row[x] = ('─', base_col)
            for j in range(len(active_cols)):
                if active_cols[j] is not None and j not in indices:
                    if j < c_min or j > c_max:
                        route_row[j*2] = ('│', col_colors[j])
            while route_row and route_row[-1][0] == " ":
                route_row.pop()
            rows.append(("routing", route_row))
            for j in indices[1:]:
                active_cols[j] = None

        col = active_cols.index(chash)
        row = [(" ", 6)] * (len(active_cols)*2)
        for j, a in enumerate(active_cols):
            if a is not None:
                row[j*2] = ('│', col_colors[j])

        is_head = (chash == head_hash)
        row[col*2] = ('◉' if is_head else '●', col_colors[col])

        parents = c["parents"]
        if len(parents) > 0:
            p1 = parents[0]
            active_cols[col] = p1
            for p in parents[1:]:
                if p in active_cols:
                    d = active_cols.index(p)
                    if d > col:
                        row[d*2] = ('┤', col_colors[d])
                        for x in range(col*2+1, d*2):
                            if x % 2 == 0:
                                row[x] = ('┼', col_colors[x//2]) if active_cols[x//2] is not None else ('─', col_colors[col])
                            else:
                                row[x] = ('─', col_colors[col])
                    elif d < col:
                        row[d*2] = ('├', col_colors[d])
                        for x in range(d*2+1, col*2):
                            if x % 2 == 0:
                                row[x] = ('┼', col_colors[x//2]) if active_cols[x//2] is not None else ('─', col_colors[d])
                            else:
                                row[x] = ('─', col_colors[d])
                else:
                    if None in active_cols[col+1:]:
                        d = active_cols.index(None, col+1)
                        col_colors[d] = next_color % 6
                        next_color += 1
                    else:
                        active_cols.append(None)
                        d = len(active_cols) - 1
                        col_colors.append(next_color % 6)
                        next_color += 1
                        row.extend([(" ", 6), (" ", 6)])
                    active_cols[d] = p
                    row[d*2] = ('╮', col_colors[col])
                    for x in range(col*2+1, d*2):
                        if x % 2 == 0:
                            row[x] = ('┼', col_colors[x//2]) if active_cols[x//2] is not None else ('─', col_colors[col])
                        else:
                            row[x] = ('─', col_colors[col])
        else:
            active_cols[col] = None

        while active_cols and active_cols[-1] is None:
            active_cols.pop()
        while row and row[-1][0] == " ":
            row.pop()

        rows.append(("commit", row, i))
    return rows

