            self.stdscr.attroff(bg_attr)
            y += 1

        detail_w = w // 2
        files_w = w - detail_w
        box_y = commits_h
        box_h = h - 1 - commits_h

        self.stdscr.attron(curses.color_pair(7))
        self.stdscr.addstr(box_y, 0, "┌ Commit Detail " + "─" * max(0, detail_w - 17) + "┐┌ Changed Files " + "─" * max(0, files_w - 18) + "┐")
        for y in range(box_y + 1, box_y + box_h - 1):
            self.stdscr.addstr(y, 0, "│")
            self.stdscr.addstr(y, detail_w - 1, "││")
            self.stdscr.addstr(y, w - 1, "│")
        self.stdscr.addstr(box_y + box_h - 1, 0, "└" + "─" * max(0, detail_w - 2) + "┘└" + "─" * max(0, files_w - 2) + "┘")
        self.stdscr.attroff(curses.color_pair(7))

        if self.commits:
            c = self.commits[self.cursor]
            self.stdscr.addstr(box_y + 1, 1, "Commit: ", curses.color_pair(10) | curses.A_BOLD)
            self.stdscr.addstr(box_y + 1, 9, c["hash"][:detail_w-10], curses.color_pair(4))
            self.stdscr.addstr(box_y + 2, 1, "Author: ", curses.color_pair(10) | curses.A_BOLD)
            self.stdscr.addstr(box_y + 2, 9, c["author"][:detail_w-10], curses.color_pair(1))
            self.stdscr.addstr(box_y + 3, 1, "Date:   ", curses.color_pair(10) | curses.A_BOLD)
            self.stdscr.addstr(box_y + 3, 9, c["date_full"][:detail_w-10], curses.color_pair(7))
            if c["parents"]:
                self.stdscr.addstr(box_y + 4, 1, "Parent: ", curses.color_pair(10) | curses.A_BOLD)
                self.stdscr.addstr(box_y + 4, 9, ", ".join(p[:7] for p in c["parents"])[:detail_w-10], curses.color_pair(7))

            full_msg = run_git(["show", "-s", "--format=%B", c["hash"]]).splitlines()
            for i, m in enumerate(full_msg[:box_h - 7]):
                if box_y + 6 + i < box_y + box_h - 1:
                    self.stdscr.addstr(box_y + 6 + i, 1, m[:detail_w - 2])

            diff_tree = run_git(["diff", "--numstat", c["parents"][0], c["hash"]] if c["parents"] else ["diff-tree", "--root", "--numstat", c["hash"]])
            added, deleted, files = 0, 0, 0
            for l in diff_tree.splitlines():
                parts = l.split()
                if len(parts) >= 3:
                    files += 1
                    try:
                        added += int(parts[0])
                        deleted += int(parts[1])
                    except: pass
            self.stdscr.addstr(box_y + 1, detail_w + 1, f"{files} files changed ", curses.color_pair(10) | curses.A_BOLD)
            self.stdscr.addstr(box_y + 1, detail_w + 18, f"+{added} ", curses.color_pair(2))
            self.stdscr.addstr(box_y + 1, detail_w + 18 + len(str(added)) + 2, f"-{deleted}", curses.color_pair(5))

            name_status = run_git(["diff", "--name-status", c["parents"][0], c["hash"]] if c["parents"] else ["diff-tree", "--root", "--name-status", c["hash"]])
            for i, l in enumerate(name_status.splitlines()[:box_h - 4]):
                parts = l.split("\t", 1)
                if len(parts) == 2:
                    status, name = parts
                    col = 2 if status.startswith('A') else 5 if status.startswith('D') else 4
                    self.stdscr.addstr(box_y + 3 + i, detail_w + 2, status[0], curses.color_pair(col))
                    self.stdscr.addstr(box_y + 3 + i, detail_w + 4, name[:files_w - 6])

        y = h - 1
        self.stdscr.attron(curses.color_pair(41))
        self.stdscr.addstr(y, 0, f" {self.repo} "[:w])
        self.stdscr.attroff(curses.color_pair(41))

        branch_text = self.head
        if self.commits:
            c = self.commits[self.cursor]
            if c["tags"]: branch_text = c["tags"][self.tag_idx[self.cursor]]

        x = len(f" {self.repo} ") + 1
        if x < w:
            self.stdscr.attron(curses.color_pair(42))
            self.stdscr.addstr(y, x, f" {branch_text} "[:w-x])
            self.stdscr.attroff(curses.color_pair(42))

        x += len(f" {branch_text} ") + 1
        if self.search_mode or self.branch_mode:
            keys = [("Enter", "confirm"), ("Esc", "cancel")]
        elif self.help_mode:
            keys = [("Esc/q", "close help")]
        else:
            keys = [("j/k", "move"), ("Enter", "checkout"), ("b", "branch"), ("f", "fetch"), ("?", "help"), ("q", "quit")]
        for k, v in keys:
            if x < w:
                self.stdscr.attron(curses.color_pair(43) | curses.A_BOLD)
                self.stdscr.addstr(y, x, f" {k} "[:w-x])
                self.stdscr.attroff(curses.color_pair(43) | curses.A_BOLD)
            x += len(k) + 2
            if x < w:
                self.stdscr.attron(curses.color_pair(44))
                self.stdscr.addstr(y, x, v[:w-x])
                self.stdscr.attroff(curses.color_pair(44))
            x += len(v) + 1

        if self.search_mode or self.branch_mode:
            mh, mw = 10, min(60, w - 4)
            my, mx = h // 2 - mh // 2, (w - mw) // 2
            title = " Search branches " if self.search_mode else " New Branch Name "
            self.stdscr.attron(curses.color_pair(43) | curses.A_BOLD)
            self.stdscr.addstr(my, mx, "┌" + title + "─" * (mw - len(title) - 2) + "┐")
            for i in range(1, mh - 1): self.stdscr.addstr(my + i, mx, "│" + " " * (mw - 2) + "│")
            self.stdscr.addstr(my + mh - 1, mx, "└" + "─" * (mw - 2) + "┘")
            self.stdscr.attroff(curses.color_pair(43) | curses.A_BOLD)

            q = self.search_query if self.search_mode else self.branch_query
            self.stdscr.addstr(my + 2, mx + 2, (q + "_")[:mw-4], curses.color_pair(44))
            self.stdscr.addstr(my + 3, mx + 2, "─" * (mw - 4), curses.color_pair(7))

            if self.search_mode:
                for i, m in enumerate(self.search_matches[:mh - 6]):
                    if i == self.search_sel:
                        self.stdscr.addstr(my + 4 + i, mx + 2, f"▶ {m[:mw-6]}", curses.color_pair(43) | curses.A_BOLD)
                    else:
                        self.stdscr.addstr(my + 4 + i, mx + 2, f"  {m[:mw-6]}", curses.color_pair(44))
            self.stdscr.addstr(my + mh - 2, mx + 2, "Enter: confirm  Esc: cancel"[:mw-4], curses.color_pair(7))

        if self.help_mode:
            mh, mw = 20, min(60, w - 4)
            my, mx = h // 2 - mh // 2, (w - mw) // 2
            title = " Help "
            self.stdscr.attron(curses.color_pair(43) | curses.A_BOLD)
            self.stdscr.addstr(my, mx, "┌" + title + "─" * (mw - len(title) - 2) + "┐")
            for i in range(1, mh - 1): self.stdscr.addstr(my + i, mx, "│" + " " * (mw - 2) + "│")
            self.stdscr.addstr(my + mh - 1, mx, "└" + "─" * (mw - 2) + "┘")
            self.stdscr.attroff(curses.color_pair(43) | curses.A_BOLD)

            help_lines = ["Navigation", "  j / k      Move down / up", "  h / l      Select left/right branch", "  g / G      Go to top / bottom", "  @          Jump to HEAD", "", "Git Operations", "  Enter      Checkout selected branch/commit", "  b          Create new branch", "  d          Delete branch", "  f          Fetch from origin", "", "General", "  /          Search branches", "  R          Refresh manually", "  ?          Show help", "  q / Esc    Quit"]
            for i, l in enumerate(help_lines[:mh - 2]): self.stdscr.addstr(my + 1 + i, mx + 2, l[:mw - 4], curses.color_pair(44))

        self.stdscr.refresh()

def main(stdscr):
    App(stdscr)

if __name__ == "__main__":
    os.environ.setdefault('ESCDELAY', '25')
    try:
        curses.wrapper(main)
    except Exception:
        pass
