#!/bin/bash
cat << 'PYEOF' > keifu.py
import sys
import os
import subprocess
import curses
import time

def run_git(args):
    try:
        return subprocess.check_output(['git'] + args, text=True, stderr=subprocess.DEVNULL).strip()
    except Exception:
        return ""

def get_git_info():
    out = run_git(["log", "--all", "--format=%H|%P|%D|%s|%cd|%an", "--date=format:%Y-%m-%d %H:%M:%S", "--date-order"])
    if not out:
        return [], "repo", "HEAD"
    commits = []
    for line in out.splitlines():
        parts = line.split("|", 5)
        if len(parts) == 6:
            raw_tags = parts[2].split(",")
            tags = []
            for t in raw_tags:
                t = t.strip()
                if not t or "tag: " in t: continue
                if t.startswith("HEAD -> "):
                    tags.append(t[8:])
                else:
                    tags.append(t)
            commits.append({
                "hash": parts[0], "parents": parts[1].split(),
                "tags": tags, "msg": parts[3],
                "date_full": parts[4], "date_short": parts[4].split()[0],
                "author": parts[5]
            })
    toplevel = run_git(["rev-parse", "--show-toplevel"])
    repo_name = os.path.basename(toplevel) if toplevel else "repo"
    head = run_git(["branch", "--show-current"])
    if not head: head = "HEAD"
    return commits, repo_name, head

def build_graph(commits, head_hash):
    active_cols = []
    col_colors = []
    next_color = 0
    rows = []
    for i, c in enumerate(commits):
        chash = c["hash"]
        if chash not in active_cols:
            if None in active_cols:
                idx = active_cols.index(None)
                active_cols[idx] = chash
                col_colors[idx] = next_color % 6
                next_color += 1
            else:
                active_cols.append(chash)
                col_colors.append(next_color % 6)
                next_color += 1

        indices = [j for j, x in enumerate(active_cols) if x == chash]
        if len(indices) > 1:
            route_row = [(" ", 6)] * (len(active_cols)*2)
            c_min = indices[0]
            c_max = indices[-1]
            base_col = col_colors[c_min]
            route_row[c_min*2] = ('├', base_col)
            route_row[c_max*2] = ('╯', col_colors[c_max])
            for x in range(c_min*2 + 1, c_max*2):
                if x % 2 == 0:
                    col = x // 2
                    if col in indices:
                        route_row[x] = ('┴', col_colors[col])
                    else:
                        route_row[x] = ('┼', col_colors[col]) if active_cols[col] is not None else ('─', base_col)
                else:
                    route_row[x] = ('─', base_col)
            for j in range(len(active_cols)):
                if active_cols[j] is not None and j not in indices:
                    if j < c_min or j > c_max:
                        route_row[j*2] = ('│', col_colors[j])
            while route_row and route_row[-1][0] == " ":
                route_row.pop()
            rows.append(("routing", route_row))
            for j in indices[1:]:
                active_cols[j] = None

        col = active_cols.index(chash)
        row = [(" ", 6)] * (len(active_cols)*2)
        for j, a in enumerate(active_cols):
            if a is not None:
                row[j*2] = ('│', col_colors[j])

        is_head = (chash == head_hash)
        row[col*2] = ('◉' if is_head else '●', col_colors[col])

        parents = c["parents"]
        if len(parents) > 0:
            p1 = parents[0]
            active_cols[col] = p1
            for p in parents[1:]:
                if p in active_cols:
                    d = active_cols.index(p)
                    if d > col:
                        row[d*2] = ('┤', col_colors[d])
                        for x in range(col*2+1, d*2):
                            if x % 2 == 0:
                                row[x] = ('┼', col_colors[x//2]) if active_cols[x//2] is not None else ('─', col_colors[col])
                            else:
                                row[x] = ('─', col_colors[col])
                    elif d < col:
                        row[d*2] = ('├', col_colors[d])
                        for x in range(d*2+1, col*2):
                            if x % 2 == 0:
                                row[x] = ('┼', col_colors[x//2]) if active_cols[x//2] is not None else ('─', col_colors[d])
                            else:
                                row[x] = ('─', col_colors[d])
                else:
                    if None in active_cols[col+1:]:
                        d = active_cols.index(None, col+1)
                        col_colors[d] = next_color % 6
                        next_color += 1
                    else:
                        active_cols.append(None)
                        d = len(active_cols) - 1
                        col_colors.append(next_color % 6)
                        next_color += 1
                        row.extend([(" ", 6), (" ", 6)])
                    active_cols[d] = p
                    row[d*2] = ('╮', col_colors[col])
                    for x in range(col*2+1, d*2):
                        if x % 2 == 0:
                            row[x] = ('┼', col_colors[x//2]) if active_cols[x//2] is not None else ('─', col_colors[col])
                        else:
                            row[x] = ('─', col_colors[col])
        else:
            active_cols[col] = None

        while active_cols and active_cols[-1] is None:
            active_cols.pop()
        while row and row[-1][0] == " ":
            row.pop()

        rows.append(("commit", row, i))
    return rows

class App:
    def __init__(self, stdscr):
        self.stdscr = stdscr
        curses.start_color()
        curses.use_default_colors()

        if curses.COLORS >= 256:
            fg_colors = [12, 2, 5, 3, 1, 14, 8, 6, 4, 15, 0, 10, 11, 13, 9]
        else:
            fg_colors = [4, 2, 5, 3, 1, 6, 0, 6, 4, 7, 0, 2, 3, 5, 1]

        bg = 8 if curses.COLORS >= 256 else 0
        for i, fg in enumerate(fg_colors):
            curses.init_pair(i+1, fg, -1)
            curses.init_pair(i+21, fg, bg)

        curses.init_pair(41, 0, 5)
        curses.init_pair(42, 0, 2)
        curses.init_pair(43, 0, 6)
        curses.init_pair(44, 15 if curses.COLORS >= 256 else 7, -1)
        curses.init_pair(45, 0, 3)
        curses.init_pair(46, 3, -1)

        self.cursor = 0
        self.scroll = 0
        self.search_mode = False
        self.search_query = ""
        self.search_matches = []
        self.search_sel = 0
        self.branch_mode = False
        self.branch_query = ""
        self.help_mode = False
        self.last_refresh = time.time()

        self.commits = []
        self.refresh_data()
        self.run()

    def refresh_data(self):
        old_hash = self.commits[self.cursor]["hash"] if self.commits else None
        self.commits, self.repo, self.head = get_git_info()
        self.head_hash = run_git(["rev-parse", "HEAD"])
        self.rows = build_graph(self.commits, self.head_hash)

        if not hasattr(self, 'tag_idx') or len(self.tag_idx) != len(self.commits):
            self.tag_idx = [0] * len(self.commits)

        if old_hash and self.commits:
            for i, c in enumerate(self.commits):
                if c["hash"] == old_hash:
                    self.cursor = i
                    break
        if self.cursor >= len(self.commits):
            self.cursor = max(0, len(self.commits) - 1)

    def run(self):
        self.stdscr.nodelay(True)
        while True:
            self.draw()
            try:
                ch = self.stdscr.getch()
            except Exception:
                ch = -1
            if ch != -1:
                if self.search_mode:
                    if ch == 27:
                        self.search_mode = False
                    elif ch == 10 or ch == 13:
                        if self.search_matches:
                            match = self.search_matches[self.search_sel]
                            for i, c in enumerate(self.commits):
                                if match in c["tags"]:
                                    self.cursor = i
                                    break
                        self.search_mode = False
                    elif ch == curses.KEY_BACKSPACE or ch == 127 or ch == 8:
                        self.search_query = self.search_query[:-1]
                        self.update_search()
                    elif ch == curses.KEY_UP:
                        if self.search_sel > 0: self.search_sel -= 1
                    elif ch == curses.KEY_DOWN:
                        if self.search_sel < len(self.search_matches) - 1: self.search_sel += 1
                    elif 32 <= ch <= 126:
                        self.search_query += chr(ch)
                        self.update_search()
                elif self.branch_mode:
                    if ch == 27:
                        self.branch_mode = False
                    elif ch == 10 or ch == 13:
                        if self.branch_query and self.commits:
                            c = self.commits[self.cursor]
                            run_git(["branch", self.branch_query, c["hash"]])
                            self.refresh_data()
                        self.branch_mode = False
                    elif ch == curses.KEY_BACKSPACE or ch == 127 or ch == 8:
                        self.branch_query = self.branch_query[:-1]
                    elif 32 <= ch <= 126:
                        self.branch_query += chr(ch)
                elif self.help_mode:
                    if ch == 27 or ch == ord('q') or ch == ord('?'):
                        self.help_mode = False
                else:
                    if ch == ord('q') or ch == 27:
                        break
                    elif ch == ord('j') or ch == curses.KEY_DOWN:
                        if self.cursor < len(self.commits) - 1: self.cursor += 1
                    elif ch == ord('k') or ch == curses.KEY_UP:
                        if self.cursor > 0: self.cursor -= 1
                    elif ch == ord('l') or ch == curses.KEY_RIGHT or ch == ord(']'):
                        if self.commits:
                            c = self.commits[self.cursor]
                            if c["tags"]: self.tag_idx[self.cursor] = (self.tag_idx[self.cursor] + 1) % len(c["tags"])
                    elif ch == ord('h') or ch == curses.KEY_LEFT or ch == ord('['):
                        if self.commits:
                            c = self.commits[self.cursor]
                            if c["tags"]: self.tag_idx[self.cursor] = (self.tag_idx[self.cursor] - 1) % len(c["tags"])
                    elif ch == ord('g') or ch == curses.KEY_HOME:
                        self.cursor = 0
                    elif ch == ord('G') or ch == curses.KEY_END:
                        self.cursor = max(0, len(self.commits) - 1)
                    elif ch == ord('@'):
                        for i, c in enumerate(self.commits):
                            if c["hash"] == self.head_hash:
                                self.cursor = i
                                break
                    elif ch == ord('R'):
                        self.refresh_data()
                    elif ch == ord('f'):
                        run_git(["fetch"])
                        self.refresh_data()
                    elif ch == ord('b'):
                        self.branch_mode = True
                        self.branch_query = ""
                    elif ch == ord('d'):
                        if self.commits:
                            c = self.commits[self.cursor]
                            if c["tags"]:
                                tag = c["tags"][self.tag_idx[self.cursor]]
                                run_git(["branch", "-d", tag])
                                self.refresh_data()
                    elif ch == 10 or ch == 13:
                        if self.commits:
                            c = self.commits[self.cursor]
                            if c["tags"]:
                                tag = c["tags"][self.tag_idx[self.cursor]]
                                run_git(["checkout", tag])
                            else:
                                run_git(["checkout", c["hash"]])
                            self.refresh_data()
                    elif ch == ord('/'):
                        self.search_mode = True
                        self.search_query = ""
                        self.update_search()
                    elif ch == ord('?'):
                        self.help_mode = True

            if time.time() - self.last_refresh > 10:
                self.refresh_data()
                self.last_refresh = time.time()
            time.sleep(0.01)

    def update_search(self):
        all_tags = []
        for c in self.commits: all_tags.extend(c["tags"])
        seen = set()
        self.search_matches = []
        for t in all_tags:
            if t not in seen and self.search_query.lower() in t.lower():
                seen.add(t)
                self.search_matches.append(t)
        self.search_sel = 0

    def draw(self):
        self.stdscr.erase()
        h, w = self.stdscr.getmaxyx()

        commits_h = h - 10
        if commits_h < 5: commits_h = 5

        self.stdscr.attron(curses.color_pair(7))
        self.stdscr.addstr(0, 0, "┌ Commits " + "─" * max(0, w - 11) + "┐")
        for y in range(1, commits_h - 1):
            self.stdscr.addstr(y, 0, "│")
            self.stdscr.addstr(y, w - 1, "│")
        self.stdscr.addstr(commits_h - 1, 0, "└" + "─" * max(0, w - 2) + "┘")
        self.stdscr.attroff(curses.color_pair(7))

        list_h = commits_h - 2
        if self.cursor < self.scroll:
            self.scroll = self.cursor
        elif self.cursor >= self.scroll + list_h:
            self.scroll = self.cursor - list_h + 1

        y = 1
        for r in self.rows[self.scroll : self.scroll + list_h]:
            rtype, rdata = r[0], r[1]
            cidx = r[2] if len(r) > 2 else -1
            bg_offset = 20 if rtype == "commit" and cidx == self.cursor else 0
            bg_attr = curses.color_pair(bg_offset) if bg_offset else 0

            self.stdscr.attron(bg_attr)
            self.stdscr.addstr(y, 1, " " * (w - 2))

            x = 1
            for char, col in rdata:
                attr = curses.color_pair(col + 1 + bg_offset)
                if x < w - 2:
                    self.stdscr.addstr(y, x, char, attr)
                x += 1

            if rtype == "commit":
                c = self.commits[cidx]
                tags = c["tags"]
                if tags:
                    idx = self.tag_idx[cidx]
                    tag = tags[idx]
                    dot_col = next((col for char, col in rdata if char in '●◉'), 0)
                    attr = curses.color_pair(dot_col + 1 + bg_offset) | curses.A_BOLD
                    self.stdscr.addstr(y, x + 1, f"[{tag}]", attr)
                    x += len(tag) + 3
                    if len(tags) > 1:
                        self.stdscr.addstr(y, x, f" +{len(tags)-1}", curses.color_pair(bg_offset))
                        x += len(str(len(tags)-1)) + 3

                msg = c["msg"]
                author = c["author"][:8].ljust(8)
                date = c["date_short"]
                chash = c["hash"][:7]

                right_w = 10 + 8 + 7 + 4
                max_msg = w - x - right_w - 3
                if max_msg < 0: max_msg = 0
                msg_disp = msg[:max_msg].ljust(max_msg)

                self.stdscr.addstr(y, x + 1, msg_disp, curses.color_pair(bg_offset))

                rx = w - right_w - 2
                if rx > x + 1 + max_msg:
                    self.stdscr.addstr(y, rx, date, curses.color_pair(7 + bg_offset))
                    self.stdscr.addstr(y, rx + 12, author, curses.color_pair(6 + bg_offset))
                    self.stdscr.addstr(y, rx + 22, chash, curses.color_pair(4 + bg_offset))

            self.stdscr.attroff(bg_attr)
            y += 1

        detail_w = w // 2
        files_w = w - detail_w
        box_y = commits_h
        box_h = h - 1 - commits_h

        self.stdscr.attron(curses.color_pair(7))
        self.stdscr.addstr(box_y, 0, "┌ Commit Detail " + "─" * max(0, detail_w - 17) + "┐┌ Changed Files " + "─" * max(0, files_w - 18) + "┐")
        for y in range(box_y + 1, box_y + box_h - 1):
            self.stdscr.addstr(y, 0, "│")
            self.stdscr.addstr(y, detail_w - 1, "││")
            self.stdscr.addstr(y, w - 1, "│")
        self.stdscr.addstr(box_y + box_h - 1, 0, "└" + "─" * max(0, detail_w - 2) + "┘└" + "─" * max(0, files_w - 2) + "┘")
        self.stdscr.attroff(curses.color_pair(7))

        if self.commits:
            c = self.commits[self.cursor]
            self.stdscr.addstr(box_y + 1, 1, "Commit: ", curses.color_pair(10) | curses.A_BOLD)
            self.stdscr.addstr(box_y + 1, 9, c["hash"][:detail_w-10], curses.color_pair(4))
            self.stdscr.addstr(box_y + 2, 1, "Author: ", curses.color_pair(10) | curses.A_BOLD)
            self.stdscr.addstr(box_y + 2, 9, c["author"][:detail_w-10], curses.color_pair(1))
            self.stdscr.addstr(box_y + 3, 1, "Date:   ", curses.color_pair(10) | curses.A_BOLD)
            self.stdscr.addstr(box_y + 3, 9, c["date_full"][:detail_w-10], curses.color_pair(7))
            if c["parents"]:
                self.stdscr.addstr(box_y + 4, 1, "Parent: ", curses.color_pair(10) | curses.A_BOLD)
                self.stdscr.addstr(box_y + 4, 9, ", ".join(p[:7] for p in c["parents"])[:detail_w-10], curses.color_pair(7))

            full_msg = run_git(["show", "-s", "--format=%B", c["hash"]]).splitlines()
            for i, m in enumerate(full_msg[:box_h - 7]):
                if box_y + 6 + i < box_y + box_h - 1:
                    self.stdscr.addstr(box_y + 6 + i, 1, m[:detail_w - 2])

            diff_tree = run_git(["diff", "--numstat", c["parents"][0], c["hash"]] if c["parents"] else ["diff-tree", "--root", "--numstat", c["hash"]])
            added, deleted, files = 0, 0, 0
            for l in diff_tree.splitlines():
                parts = l.split()
                if len(parts) >= 3:
                    files += 1
                    try:
                        added += int(parts[0])
                        deleted += int(parts[1])
                    except: pass
            self.stdscr.addstr(box_y + 1, detail_w + 1, f"{files} files changed ", curses.color_pair(10) | curses.A_BOLD)
            self.stdscr.addstr(box_y + 1, detail_w + 18, f"+{added} ", curses.color_pair(2))
            self.stdscr.addstr(box_y + 1, detail_w + 18 + len(str(added)) + 2, f"-{deleted}", curses.color_pair(5))

            name_status = run_git(["diff", "--name-status", c["parents"][0], c["hash"]] if c["parents"] else ["diff-tree", "--root", "--name-status", c["hash"]])
            for i, l in enumerate(name_status.splitlines()[:box_h - 4]):
                parts = l.split("\t", 1)
                if len(parts) == 2:
                    status, name = parts
                    col = 2 if status.startswith('A') else 5 if status.startswith('D') else 4
                    self.stdscr.addstr(box_y + 3 + i, detail_w + 2, status[0], curses.color_pair(col))
                    self.stdscr.addstr(box_y + 3 + i, detail_w + 4, name[:files_w - 6])

        y = h - 1
        self.stdscr.attron(curses.color_pair(41))
        self.stdscr.addstr(y, 0, f" {self.repo} "[:w])
        self.stdscr.attroff(curses.color_pair(41))

        branch_text = self.head
        if self.commits:
            c = self.commits[self.cursor]
            if c["tags"]: branch_text = c["tags"][self.tag_idx[self.cursor]]

        x = len(f" {self.repo} ") + 1
        if x < w:
            self.stdscr.attron(curses.color_pair(42))
            self.stdscr.addstr(y, x, f" {branch_text} "[:w-x])
            self.stdscr.attroff(curses.color_pair(42))

        x += len(f" {branch_text} ") + 1
        if self.search_mode or self.branch_mode:
            keys = [("Enter", "confirm"), ("Esc", "cancel")]
        elif self.help_mode:
            keys = [("Esc/q", "close help")]
        else:
            keys = [("j/k", "move"), ("Enter", "checkout"), ("b", "branch"), ("f", "fetch"), ("?", "help"), ("q", "quit")]
        for k, v in keys:
            if x < w:
                self.stdscr.attron(curses.color_pair(43) | curses.A_BOLD)
                self.stdscr.addstr(y, x, f" {k} "[:w-x])
                self.stdscr.attroff(curses.color_pair(43) | curses.A_BOLD)
            x += len(k) + 2
            if x < w:
                self.stdscr.attron(curses.color_pair(44))
                self.stdscr.addstr(y, x, v[:w-x])
                self.stdscr.attroff(curses.color_pair(44))
            x += len(v) + 1

        if self.search_mode or self.branch_mode:
            mh, mw = 10, min(60, w - 4)
            my, mx = h // 2 - mh // 2, (w - mw) // 2
            title = " Search branches " if self.search_mode else " New Branch Name "
            self.stdscr.attron(curses.color_pair(43) | curses.A_BOLD)
            self.stdscr.addstr(my, mx, "┌" + title + "─" * (mw - len(title) - 2) + "┐")
            for i in range(1, mh - 1): self.stdscr.addstr(my + i, mx, "│" + " " * (mw - 2) + "│")
            self.stdscr.addstr(my + mh - 1, mx, "└" + "─" * (mw - 2) + "┘")
            self.stdscr.attroff(curses.color_pair(43) | curses.A_BOLD)

            q = self.search_query if self.search_mode else self.branch_query
            self.stdscr.addstr(my + 2, mx + 2, (q + "_")[:mw-4], curses.color_pair(44))
            self.stdscr.addstr(my + 3, mx + 2, "─" * (mw - 4), curses.color_pair(7))

            if self.search_mode:
                for i, m in enumerate(self.search_matches[:mh - 6]):
                    if i == self.search_sel:
                        self.stdscr.addstr(my + 4 + i, mx + 2, f"▶ {m[:mw-6]}", curses.color_pair(43) | curses.A_BOLD)
                    else:
                        self.stdscr.addstr(my + 4 + i, mx + 2, f"  {m[:mw-6]}", curses.color_pair(44))
            self.stdscr.addstr(my + mh - 2, mx + 2, "Enter: confirm  Esc: cancel"[:mw-4], curses.color_pair(7))

        if self.help_mode:
            mh, mw = 20, min(60, w - 4)
            my, mx = h // 2 - mh // 2, (w - mw) // 2
            title = " Help "
            self.stdscr.attron(curses.color_pair(43) | curses.A_BOLD)
            self.stdscr.addstr(my, mx, "┌" + title + "─" * (mw - len(title) - 2) + "┐")
            for i in range(1, mh - 1): self.stdscr.addstr(my + i, mx, "│" + " " * (mw - 2) + "│")
            self.stdscr.addstr(my + mh - 1, mx, "└" + "─" * (mw - 2) + "┘")
            self.stdscr.attroff(curses.color_pair(43) | curses.A_BOLD)

            help_lines = ["Navigation", "  j / k      Move down / up", "  h / l      Select left/right branch", "  g / G      Go to top / bottom", "  @          Jump to HEAD", "", "Git Operations", "  Enter      Checkout selected branch/commit", "  b          Create new branch", "  d          Delete branch", "  f          Fetch from origin", "", "General", "  /          Search branches", "  R          Refresh manually", "  ?          Show help", "  q / Esc    Quit"]
            for i, l in enumerate(help_lines[:mh - 2]): self.stdscr.addstr(my + 1 + i, mx + 2, l[:mw - 4], curses.color_pair(44))

        self.stdscr.refresh()

def main(stdscr):
    App(stdscr)

if __name__ == "__main__":
    os.environ.setdefault('ESCDELAY', '25')
    try:
        curses.wrapper(main)
    except Exception:
        pass
